package com.bank.eod.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "settled_trades")
public class SettledTrade {

    @Id
    @Column(name = "settlement_id")
    private String settlementId;

    @Column(name = "trade_id")
    private String tradeId;

    @Column(name = "account_id")
    private String accountId;

    private BigDecimal amount;
    private BigDecimal fee;

    @Column(name = "net_amount")
    private BigDecimal netAmount;

    @Column(name = "settled_at")
    private LocalDateTime settledAt;

    protected SettledTrade() {}

    public SettledTrade(String settlementId, String tradeId, String accountId,
                         BigDecimal amount, BigDecimal fee) {
        this.settlementId = settlementId;
        this.tradeId = tradeId;
        this.accountId = accountId;
        this.amount = amount;
        this.fee = fee;
        this.netAmount = amount.subtract(fee);
        this.settledAt = LocalDateTime.now();
    }

    public String getSettlementId() { return settlementId; }
    public BigDecimal getNetAmount() { return netAmount; }
}
