// ItemProcessor: transforms PendingTrade → SettledTrade (business logic per item)
package com.bank.eod.batch;

import com.bank.eod.model.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.UUID;

@Component
@Slf4j
public class SettlementProcessor implements ItemProcessor<PendingTrade, SettledTrade> {

    @Value("${batch.fee-rate:0.001}")
    private BigDecimal feeRate;

    @Override
    public SettledTrade process(PendingTrade trade) {
        BigDecimal amount = trade.getPrice().multiply(BigDecimal.valueOf(trade.getQuantity()));
        BigDecimal fee = amount.multiply(feeRate).setScale(2, RoundingMode.HALF_UP);

        String settlementId = "STL-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();

        log.debug("Processing: {} {} x{} → amount={}, fee={}",
            trade.getTradeId(), trade.getSymbol(), trade.getQuantity(), amount, fee);

        return new SettledTrade(settlementId, trade.getTradeId(), trade.getAccountId(), amount, fee);
    }
}
