// Spring Batch: read pending trades → calculate settlement → write to settled_trades
// Chunk-oriented: read 100, process 100, write 100, COMMIT. Repeat.
package com.bank.eod.batch;

import com.bank.eod.event.BatchCompletedEvent;
import com.bank.eod.model.*;
import jakarta.persistence.EntityManagerFactory;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.batch.core.*;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.database.*;
import org.springframework.batch.item.database.builder.JpaPagingItemReaderBuilder;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

@Configuration
@RequiredArgsConstructor
@Slf4j
public class BatchConfig {

    private final SettlementProcessor processor;
    private final ApplicationEventPublisher eventPublisher;

    @Bean
    JpaPagingItemReader<PendingTrade> tradeReader(EntityManagerFactory emf) {
        return new JpaPagingItemReaderBuilder<PendingTrade>()
            .name("tradeReader")
            .entityManagerFactory(emf)
            .queryString("SELECT t FROM PendingTrade t WHERE t.status = 'PENDING'")
            .pageSize(100)
            .build();
    }

    @Bean
    JpaItemWriter<SettledTrade> settlementWriter(EntityManagerFactory emf) {
        JpaItemWriter<SettledTrade> writer = new JpaItemWriter<>();
        writer.setEntityManagerFactory(emf);
        return writer;
    }

    @Bean
    Step settlementStep(JobRepository jobRepo, PlatformTransactionManager txManager,
                         JpaPagingItemReader<PendingTrade> reader,
                         JpaItemWriter<SettledTrade> writer,
                         @Value("${batch.chunk-size:100}") int chunkSize) {
        return new StepBuilder("settlementStep", jobRepo)
            .<PendingTrade, SettledTrade>chunk(chunkSize, txManager)  // 100 items per chunk
            .reader(reader)        // read 100 pending trades
            .processor(processor)  // calculate settlement for each
            .writer(writer)        // write 100 settled trades, COMMIT
            .faultTolerant()
            .skip(Exception.class)     // skip failed items
            .skipLimit(10)             // max 10 skips before job fails
            .retry(Exception.class)    // retry on transient errors
            .retryLimit(3)
            .build();
    }

    @Bean
    Job eodSettlementJob(JobRepository jobRepo, Step settlementStep) {
        return new JobBuilder("eodSettlementJob", jobRepo)
            .start(settlementStep)
            .listener(new JobExecutionListenerSupport() {
                @Override
                public void afterJob(JobExecution jobExecution) {
                    long processed = jobExecution.getStepExecutions().stream()
                        .mapToLong(StepExecution::getWriteCount).sum();
                    log.info("Batch completed: {} trades settled, status={}",
                        processed, jobExecution.getStatus());
                    eventPublisher.publishEvent(new BatchCompletedEvent(processed));
                }
            })
            .build();
    }
}
