// SmartLifecycle: deterministic start/stop ordering — starts BEFORE batch, stops AFTER
package com.bank.eod.lifecycle;

import lombok.extern.slf4j.Slf4j;
import org.springframework.context.SmartLifecycle;
import org.springframework.stereotype.Component;

@Component
@Slf4j
public class ExchangeConnectionManager implements SmartLifecycle {

    private volatile boolean running = false;

    @Override
    public void start() {
        log.info("[LIFECYCLE] Connecting to exchange (phase=0 — starts FIRST)");
        running = true;
    }

    @Override
    public void stop() {
        log.info("[LIFECYCLE] Disconnecting from exchange (phase=0 — stops LAST)");
        running = false;
    }

    @Override
    public boolean isRunning() { return running; }

    @Override
    public int getPhase() { return 0; }  // lower phase = starts first, stops last
}
